export type ParsedLendingPoolAddBankKaminoInstruction<
  TProgram extends string = typeof MARGINFI_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    group: TAccountMetas[0];
    admin: TAccountMetas[1];
    feePayer: TAccountMetas[2];
    /**
     * Must match the mint used by the Kamino reserve (integration_acc_1), Kamino calls this the
     * `reserve_liquidity_mint` aka `liquidity.mint_pubkey`
     */
    bankMint: TAccountMetas[3];
    bank: TAccountMetas[4];
    integrationAcc1: TAccountMetas[5];
    /** Note: not yet initialized in this instruction, run `init_obligation` after. */
    integrationAcc2: TAccountMetas[6];
    /**
     * Will be authority of the bank's Kamino obligation (integration_acc_2). Note: When
     * depositing/withdrawing Kamino assets, the source/destination must also be owned by the
     * obligation authority.
     * Kamino assets, the source/destination must also be owned by the obligation authority. This
     * account owns the `liquidity_vault`, and thus acts as intermediary for deposits/withdraws
     */
    liquidityVaultAuthority: TAccountMetas[7];
    /**
     * For Kamino banks, the `liquidity_vault` never holds assets, but is instead used as an
     * intermediary when depositing/withdrawing, e.g., withdrawn funds move from Kamino -> here ->
     * the user's token account.
     */
    liquidityVault: TAccountMetas[8];
    /** Note: Currently does nothing. */
    insuranceVaultAuthority: TAccountMetas[9];
    /** Note: Currently does nothing. */
    insuranceVault: TAccountMetas[10];
    /** Note: Currently does nothing. */
    feeVaultAuthority: TAccountMetas[11];
    /** Note: Currently does nothing. */
    feeVault: TAccountMetas[12];
    tokenProgram: TAccountMetas[13];
    systemProgram: TAccountMetas[14];
  };
  data: LendingPoolAddBankKaminoInstructionData;
};

export function parseLendingPoolAddBankKaminoInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedLendingPoolAddBankKaminoInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 15) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 15,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      group: getNextAccount(),
      admin: getNextAccount(),
      feePayer: getNextAccount(),
      bankMint: getNextAccount(),
      bank: getNextAccount(),
      integrationAcc1: getNextAccount(),
      integrationAcc2: getNextAccount(),
      liquidityVaultAuthority: getNextAccount(),
      liquidityVault: getNextAccount(),
      insuranceVaultAuthority: getNextAccount(),
      insuranceVault: getNextAccount(),
      feeVaultAuthority: getNextAccount(),
      feeVault: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getLendingPoolAddBankKaminoInstructionDataDecoder().decode(instruction.data),
  };
}
